SELECT 'gongkao', '反驳/辩论题', 'kp-ms-nov-debate', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "新颖题型：反驳/辩论题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "破立结合。先指出对方观点的漏洞，再建立自己的严密逻辑。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“有人说年轻人就应该去大城市拼搏，回小县城就是躺平。请你进行反驳。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、反驳的三个层次"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反驳前提：对方的前提是“小县城没有挑战”。反驳：现代小县城的基层治理、乡村振兴同样面临巨大挑战，需要高素质人才去攻坚克难。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反驳论据：对方认为“大城市才有大作为”。反驳：无数扎根基层的大学生村官，在田间地头同样干出了惊天动地的事业。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反驳逻辑（绝对化）：对方把“去哪儿”和“是否躺平”画等号是逻辑谬误。躺平是一种心态，而不是地理位置。在大城市混日子也是躺平，在小县城造福一方就是拼搏！"}]}]}]}]}$$ AS jsonb), NULL, '反驳/辩论题的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "新颖题型", "反驳题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_nov_debate", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
